<script lang="ts">
 import IslandPortrait from './IslandPortrait.svelte';
 import {onMount} from 'svelte';import {companion,updateData,notify} from '../state.svelte';import {normalizeWardrobe,defaultWardrobe,loadWardrobe,drawWardrobe} from '../wardrobe';import {canvasContext,observeCanvas} from '../canvas';
 let {onapply=()=>{}}=$props<{onapply?:()=>void}>();
 let draft=$state(normalizeWardrobe(companion.data.preferences.customAvatar)),loading=$state(true),failure=$state(''),systemReduced=$state(false);
 let canvas:HTMLCanvasElement,assets:Awaited<ReturnType<typeof loadWardrobe>>,loop:ReturnType<typeof observeCanvas>,greeting:number|undefined;
 const sections=[{key:'outfit',label:'衣服款式',options:[['hoodie','云朵连帽衫'],['cardigan','软绒针织衫'],['sailor','星屿水手服']]},{key:'color',label:'衣服色调',options:[['lilac','淡紫'],['rose','樱粉'],['cream','奶油']]},{key:'hairColor',label:'头发颜色',options:[['lilac','原色淡紫'],['rose','柔雾樱粉']]},{key:'accessory',label:'胸前配饰',options:[['none','不加胸饰'],['star','星星胸针'],['flower','小花胸针']]}] as const;
 function draw(time:number){const c=canvasContext(canvas);if(!c||!assets)return;const size=Math.min(c.width,c.height)*.96;c.ctx.save();c.ctx.translate((c.width-size)/2,(c.height-size)/2);c.ctx.scale(size/512,size/512);drawWardrobe(c.ctx,assets,draft,time,{still:systemReduced||companion.data.preferences.reduceMotion,greetingAt:greeting});c.ctx.restore();}
 function choose(key:string,value:string){draft={...draft,[key]:value};}
 function save(){try{updateData(data=>{data.preferences.customAvatar=normalizeWardrobe(draft);data.preferences.avatar='custom';});onapply();notify('小屿换上了你选的衣服，房间形象已同步。');}catch(e){notify(String(e));}}
 $effect(()=>{draft;systemReduced;companion.data.preferences.reduceMotion;loop?.invalidate();});
 onMount(()=>{let active=true;const media=matchMedia('(prefers-reduced-motion: reduce)'),change=()=>systemReduced=media.matches;change();media.addEventListener('change',change);loop=observeCanvas(canvas,draw,()=>systemReduced||companion.data.preferences.reduceMotion,0);void loadWardrobe().then(data=>{if(active){assets=data;loading=false;loop.invalidate();}}).catch(e=>{if(active){failure=String(e);loading=false;}});return()=>{active=false;loop.destroy();media.removeEventListener('change',change);};});
</script>
<section class="xy-panel wardrobe" aria-label="小屿本人的完整造型衣橱"><div class="wardrobe-title"><h2>小屿的像素衣橱</h2><p>每一套都是完整的小屿，换上喜欢的衣服吧。</p></div>
 <div class="wardrobe-layout"><div class="wardrobe-stage"><canvas bind:this={canvas} aria-label="小屿本人换装预览" data-character="xiaoyu-original"></canvas>{#if loading}<p role="status">正在整理小屿的衣橱…</p>{/if}{#if failure}<p role="alert">{failure}</p>{/if}<button class="xy-btn" disabled={loading||!!failure} onclick={()=>{greeting=performance.now();loop.invalidate();}}>让小屿打个招呼</button><p>今天，想穿哪一套？</p><div class="island-outfit"><IslandPortrait config={draft}/><p><strong>岛上的出门装</strong>同一个小屿，岛上和房间同步衣服、色调与发色。</p></div></div>
 <div class="wardrobe-options">{#each sections as section}<fieldset><legend>{section.label}</legend><div>{#each section.options as option}<button class:chosen={draft[section.key]===option[0]} aria-pressed={draft[section.key]===option[0]} onclick={()=>choose(section.key,option[0])}>{option[1]}</button>{/each}</div></fieldset>{/each}<div class="xy-actions"><button class="xy-btn primary" disabled={loading||!!failure} onclick={save}>保存并使用这套形象</button><button class="xy-btn" onclick={()=>draft=normalizeWardrobe(companion.data.preferences.customAvatar)}>撤销衣橱预览</button><button class="text-button" onclick={()=>draft={...defaultWardrobe}}>恢复初始搭配</button></div></div></div>
</section>
<style>
 .wardrobe{margin-top:24px}.wardrobe-title p{margin-top:9px;color:var(--xy-secondary);font-size:14px}.wardrobe-layout{display:grid;grid-template-columns:minmax(260px,.9fr) 1.1fr;gap:32px;margin-top:24px;align-items:start}.wardrobe-stage{position:sticky;top:10px;background:var(--xy-page);border-radius:12px;text-align:center;padding:14px 18px 20px}.wardrobe-stage canvas{display:block;width:100%;height:340px;aspect-ratio:1;image-rendering:auto}.wardrobe-stage>p{font-size:12px;color:var(--xy-secondary);margin-top:12px}.wardrobe-options fieldset{border:0;padding:0;margin:0 0 20px}.wardrobe-options legend{font-size:14px;font-weight:600;margin-bottom:9px}.wardrobe-options fieldset>div{display:flex;gap:8px;flex-wrap:wrap}.wardrobe-options fieldset button{min-height:44px;border:1px solid var(--xy-border);border-radius:8px;padding:8px 13px;color:var(--xy-ink);background:var(--xy-panel);font-size:14px}.wardrobe-options button.chosen{background:var(--xy-selected);border-color:var(--xy-accent)}.wardrobe-options .xy-actions{margin-top:18px}@media(max-width:700px){.wardrobe-layout{grid-template-columns:1fr;gap:22px}.wardrobe-stage{top:8px;z-index:2;padding:8px 12px 12px}.wardrobe-stage canvas{height:200px}.wardrobe-stage>p{display:none}.wardrobe-options button{scroll-margin-top:300px}}
.island-outfit{display:flex;align-items:center;justify-content:center;gap:14px;border-top:1px solid var(--xy-border);margin-top:16px;padding-top:12px;text-align:left}.island-outfit p{font-size:12px;color:var(--xy-secondary);line-height:1.8;max-width:24ch}.island-outfit strong{display:block;font-size:14px;color:var(--xy-ink);margin-bottom:4px}</style>
